import{_ as t,o as a,c as n,a3 as i}from"./chunks/framework.CRbjHCyB.js";const u=JSON.parse('{"title":"Compile Task Graph and Module Compilation","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Compile Task Graph and Module Compilation | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/clice/design/task-graph"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/clice/design/task-graph"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/clice/design/task-graph"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/clice/design/task-graph"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/clice/design/task-graph"}]]},"headers":[],"relativePath":"clice/design/task-graph.md","filePath":"en/clice/design/task-graph.md","lastUpdated":1788608563000}'),s={name:"clice/design/task-graph.md"};function o(r,e,l,d,c,h){return a(),n("div",null,[...e[0]||(e[0]=[i(`<h1 id="compile-task-graph-and-module-compilation" tabindex="-1">Compile Task Graph and Module Compilation <a class="header-anchor" href="#compile-task-graph-and-module-compilation" aria-label="Permalink to &quot;Compile Task Graph and Module Compilation&quot;">​</a></h1><h2 id="background" tabindex="-1">Background <a class="header-anchor" href="#background" aria-label="Permalink to &quot;Background&quot;">​</a></h2><p>C++20 introduced modules, changing the independent compilation model that C++ has used since its inception. In traditional C++, each source file compiles independently into an object file, sharing declarations between files via headers. Modules break this independence:</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// math.cppm — module interface unit</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> module</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> math;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> int</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> add</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> a, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> b) { </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> a </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> b; }</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// main.cpp — imports the module</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">import math;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> main</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() { </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> add</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">); }</span></span></code></pre></div><p>Before compiling <code>main.cpp</code>, the module interface unit <code>math.cppm</code> must be compiled first, producing a precompiled module file (PCM). If a project has multi-level module dependencies — A imports B, B imports C — the compilation order must be C → B → A. This forms a directed acyclic graph (DAG), where nodes are module files and edges are <code>import</code> relationships.</p><p>Build systems (CMake, Ninja, etc.) are naturally suited for this kind of DAG scheduling: scan all files, build a complete dependency graph, compile in topological order. But a language server faces different challenges:</p><p><strong>Real-time requirements.</strong> After a user opens a file that imports modules, they expect editing feedback within hundreds of milliseconds. Waiting for the entire module graph to compile is unacceptable. A language server needs a lazy, on-demand compilation strategy — compile only the modules the current file actually needs.</p><p><strong>Cascading file changes.</strong> When the user modifies a module interface file and saves, all PCMs of modules that directly or indirectly depend on it become stale. The language server must detect this, cancel in-progress compilations, mark affected modules as dirty, and recompile them when next needed.</p><p><strong>Concurrency and cancellation.</strong> Multiple files may simultaneously need the same module&#39;s PCM. The language server must avoid duplicate compilations and let later requests wait for earlier ones to finish. At the same time, when the user closes the file that triggered a compilation and no longer needs a module, the in-progress compilation should be cancellable to free resources.</p><p><strong>Temporary cyclic dependencies.</strong> Although C++ modules do not allow circular <code>import</code>s, users may temporarily introduce cycles during editing. The language server must detect and report errors rather than deadlocking.</p><p>In clangd, C++20 module support has long been in an experimental stage, lacking dedicated design. <a href="https://github.com/clangd/clangd/issues/1293" target="_blank" rel="noreferrer">clangd/clangd#1293</a> is the clangd team&#39;s summary of the module support problem — concluding that &quot;these are not just bugs that can be fixed, a design and new infrastructure is needed,&quot; and at the time &quot;nobody has plans/availability to work on this soon.&quot; Years later, related issues continue to appear: <a href="https://github.com/clangd/clangd/issues/2569" target="_blank" rel="noreferrer">clangd/clangd#2569</a> lists critical missing features in modules (rename, find references, etc.); <a href="https://github.com/clangd/clangd/issues/2292" target="_blank" rel="noreferrer">clangd/clangd#2292</a> and <a href="https://github.com/clangd/clangd/issues/2497" target="_blank" rel="noreferrer">clangd/clangd#2497</a> report file-locking conflicts caused by clangd sharing PCM files with the build system — clangd holds the PCM open, preventing the build system from overwriting it.</p><p>The common root cause of these problems is the lack of a compilation scheduling system designed for language server use cases. clice addresses this with a general <strong>compile task graph</strong>: every expensive build product — module PCMs, preamble PCHs, document ASTs, one-shot batch runs — is a node in one graph, with lazy construction, on-demand compilation, real-time cooperative cancellation, and dependency cascading. Modules are the richest client of the graph, and this page uses them as the running example.</p><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to &quot;Design&quot;">​</a></h2><h3 id="one-graph-several-node-families" tabindex="-1">One Graph, Several Node Families <a class="header-anchor" href="#one-graph-several-node-families" aria-label="Permalink to &quot;One Graph, Several Node Families&quot;">​</a></h3><p>The task graph itself is deliberately thin: it knows about nodes, edges, interest, rounds, and invalidation — and nothing about what a node builds. What a node <em>means</em> is defined by its <strong>family</strong>:</p><ul><li><strong>PCM family</strong>: one node per module, edges are <code>import</code> relationships. This is where all module-specific policy lives.</li><li><strong>PCH family</strong>: one node per preamble content key — files whose preambles are identical share one node and one build.</li><li><strong>AST family</strong>: one node per open document, producing the published feature results.</li><li><strong>TU-run family</strong>: one-shot translation-unit runs shared by background indexing and batch lint.</li></ul><p>The rest of this section describes the graph&#39;s general contract; module-specific behavior is called out explicitly.</p><h3 id="lazy-construction" tabindex="-1">Lazy Construction <a class="header-anchor" href="#lazy-construction" aria-label="Permalink to &quot;Lazy Construction&quot;">​</a></h3><p>Unlike build systems that scan all files and build a complete DAG before compilation, the graph is lazily constructed — a node is created only when a compilation request first reaches it, and each of its build rounds re-resolves that node&#39;s dependencies. When the user opens a file, only the module chain actually needed by that file is scanned and compiled, not the entire project&#39;s module graph.</p><p>Two module entry points exist:</p><ul><li><strong>Compile module</strong>: Compile the specified module and all its transitive dependencies, producing a PCM file. Used for module interface units themselves.</li><li><strong>Compile dependencies</strong>: Compile all module dependencies of the specified file, but not the file itself. Used for ordinary source files — they are not part of the module DAG but may use modules via <code>import</code>.</li></ul><p>An <code>import</code> whose provider cannot be resolved yet does not fail the graph: it becomes a <strong>placeholder node</strong> that is never run, only depended upon. When a provider appears later — the file is created, or a compilation database reload reveals it — the graph updates the edge and invalidates dependents, which then rebuild against the real module.</p><h3 id="interest-counting" tabindex="-1">Interest Counting <a class="header-anchor" href="#interest-counting" aria-label="Permalink to &quot;Interest Counting&quot;">​</a></h3><p>Interest counting is the graph&#39;s core scheduling mechanism, tracking &quot;how many active requests currently care about a given node.&quot; It answers two questions: should compilation be started? Can compilation be cancelled?</p><p>When a request needs a node, the node&#39;s interest is acquired; when the request finishes or is cancelled, it is released. Interest reaching zero means no active request currently cares about this product.</p><p>Interest operates at two levels: request-level and dependency-level. Request-level interest means &quot;this request is waiting for the product&quot;; dependency-level interest means &quot;this node&#39;s build is waiting for its direct dependencies to complete.&quot; The latter ensures a module is not prematurely cancelled when another module&#39;s build depends on it, even if the original request has been cancelled.</p><h3 id="compilation-rounds" tabindex="-1">Compilation Rounds <a class="header-anchor" href="#compilation-rounds" aria-label="Permalink to &quot;Compilation Rounds&quot;">​</a></h3><p>Each build attempt constitutes a round. Concurrent requests for the same node join the running round instead of spawning their own; waiters learn of completion through the round&#39;s outcome and decide their next action. A round has three possible outcomes:</p><ul><li><strong>Success</strong>: product built, dirty flag cleared</li><li><strong>Failed</strong>: compilation error (dependency failure, cycle detection, etc.), dirty flag retained</li><li><strong>Stale</strong>: the round was superseded (file modified during compilation, or interest dropped), waiters automatically drive a new round</li></ul><p>Failure is not sticky — retaining the dirty flag means that after the user fixes an error, the next request naturally triggers a retry without requiring a server restart.</p><h3 id="cooperative-cancellation" tabindex="-1">Cooperative Cancellation <a class="header-anchor" href="#cooperative-cancellation" aria-label="Permalink to &quot;Cooperative Cancellation&quot;">​</a></h3><p>Cancellation is advisory, never destructive. Dropping interest to zero (or superseding a round) raises a stop flag; the running build observes it at declaration-level checkpoints inside the compile and winds down early, and the round publishes a real outcome to its waiters. A running round is never torn down mid-flight — which means the commit sequence at the end of a build (write the artifact, then register its metadata) always runs to completion once started, so cancellation can never leave a half-registered product behind.</p><h3 id="dirty-state-and-generation-counter" tabindex="-1">Dirty State and Generation Counter <a class="header-anchor" href="#dirty-state-and-generation-counter" aria-label="Permalink to &quot;Dirty State and Generation Counter&quot;">​</a></h3><p>Each node uses a dirty flag to indicate that a rebuild is needed. The generation counter is a monotonically increasing value, incremented on each file update, used to detect asynchronous races: the build records the current generation at start and compares upon completion — a mismatch means the file was modified during compilation, and the result is stale.</p><h3 id="dependencies" tabindex="-1">Dependencies <a class="header-anchor" href="#dependencies" aria-label="Permalink to &quot;Dependencies&quot;">​</a></h3><p>Module nodes maintain forward dependencies (modules they import) and reverse dependencies (modules importing them). Forward dependencies are obtained via lazy resolution; reverse dependencies are back-filled at resolution time. Reverse dependencies are the basis for cascading notifications on file changes — starting from the modified module, following reverse edges finds all affected modules.</p><p>The module name to file mapping is maintained by DependencyGraph (see <a href="./dependency-scanning">Dependency Scanning</a>) — the startup fast scan discovers all module declarations and builds a module name → file path registry. The PCM family uses this registry to resolve <code>import</code> statements to concrete file paths.</p><h2 id="implementation" tabindex="-1">Implementation <a class="header-anchor" href="#implementation" aria-label="Permalink to &quot;Implementation&quot;">​</a></h2><h3 id="compilation-flow" tabindex="-1">Compilation Flow <a class="header-anchor" href="#compilation-flow" aria-label="Permalink to &quot;Compilation Flow&quot;">​</a></h3><p>The complete flow of a module compilation request:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Request enters</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ├─ Acquire interest on the target module&#39;s node</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ├─ Target not dirty? ──→ Return immediately (PCM available)</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ├─ No round in progress? ──→ Start a build round</span></span>
<span class="line"><span>  │                             │</span></span>
<span class="line"><span>  │                             ├─ Lazily resolve dependencies (scan import declarations)</span></span>
<span class="line"><span>  │                             ├─ Check for self-cycle</span></span>
<span class="line"><span>  │                             ├─ Acquire interest on direct dependencies</span></span>
<span class="line"><span>  │                             ├─ Wait for each dependency to compile</span></span>
<span class="line"><span>  │                             ├─ Dispatch to worker process (produce PCM)</span></span>
<span class="line"><span>  │                             └─ Check generation counter ──→ Mismatch = Stale</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ├─ Join the round and wait for its outcome</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  └─ Based on result: Success → return / Failed → error / Stale → retry</span></span></code></pre></div><p>Lazy resolution uses the Clang preprocessor for precise scanning, which differs from the fast lexer-based scan used during startup <a href="./dependency-scanning">dependency scanning</a>. The fast scan does not expand macros or evaluate conditionals, suitable for building a global overview of include relationships; precise scanning expands all preprocessor directives to obtain the file&#39;s actual module dependencies under its current compile command. Resolution runs at the start of every build round rather than being cached, so a changed compile command or import list is always seen by the next round.</p><blockquote><p>Module implementation units (those with <code>module X;</code> but no <code>export</code>) implicitly depend on their corresponding module interface unit. Precise scanning detects this and automatically adds the dependency.</p></blockquote><h3 id="deferred-zero-interest-cancellation" tabindex="-1">Deferred Zero-Interest Cancellation <a class="header-anchor" href="#deferred-zero-interest-cancellation" aria-label="Permalink to &quot;Deferred Zero-Interest Cancellation&quot;">​</a></h3><p>When interest drops to zero, cancellation is not requested immediately; the check is deferred briefly — if interest is still zero at that point, cooperative cancellation proceeds.</p><p>This handles the scenario where a compilation request is superseded. When the user edits during compilation, a new request replaces the old one: the old request releases its interest (momentarily zero), then the new request re-establishes it. Immediate cancellation would unnecessarily wind down shared dependency builds; the deferral allows such handoffs to complete smoothly.</p><h3 id="cascading-updates" tabindex="-1">Cascading Updates <a class="header-anchor" href="#cascading-updates" aria-label="Permalink to &quot;Cascading Updates&quot;">​</a></h3><p>When a module file is saved (didSave), the graph performs a cascading update:</p><ol><li>Mark the saved file&#39;s node dirty, increment its generation counter, and supersede any round in flight</li><li>Traverse all transitive dependents along reverse edges — both the durable edges recorded by earlier rounds and the candidate edges of rounds still in flight; for each affected module: supersede its running round, mark dirty, increment generation</li><li>Invalidate the affected cached PCMs so nothing consumes a stale product</li></ol><p>Forward edges are left untouched: the saved file&#39;s next round rescans its <code>import</code> declarations and replaces them, so an import removed by the edit stops cascading only after that rescan. Cascading updates do not modify interest — existing waiters retain theirs. Upon observing a Stale outcome, they automatically drive a new round.</p><h3 id="cycle-detection" tabindex="-1">Cycle Detection <a class="header-anchor" href="#cycle-detection" aria-label="Permalink to &quot;Cycle Detection&quot;">​</a></h3><p>Before waiting for a dependency&#39;s compilation to complete, the graph checks for wait cycles: starting from the target node, it searches along the dependency chain, following only nodes currently being built, checking whether the chain leads back to the current waiter. If a cycle is detected, it returns failure immediately, avoiding deadlock.</p><h3 id="structured-concurrency" tabindex="-1">Structured Concurrency <a class="header-anchor" href="#structured-concurrency" aria-label="Permalink to &quot;Structured Concurrency&quot;">​</a></h3><p>All rounds run as tasks inside a task group owned by the graph, providing structured concurrency guarantees: shutdown stops intake, cancels cooperatively, and waits for frames to unwind, ensuring no dangling build tasks remain. Completed round frames are reclaimed eagerly as they finish.</p><h3 id="pcm-caching" tabindex="-1">PCM Caching <a class="header-anchor" href="#pcm-caching" aria-label="Permalink to &quot;PCM Caching&quot;">​</a></h3><p>PCM files are named by configuration, not by content: the module name plus a hash of the compiler version, working directory, source path and frontend-relevant flags, stored in a dedicated cache directory. This is fully isolated from build system artifacts, avoiding file-locking conflicts. Content changes are caught by the dependency snapshots described next, not by the name.</p><p>Cached PCMs are validated through their dependency snapshots: each dependency&#39;s identity and observed content version are checked against the shared file table (stat fast path, content hash confirmation — see <a href="./incremental-parse">Incremental Compilation</a>). Recompilation only occurs when dependency content has actually changed, avoiding unnecessary rebuilds caused by &quot;touch without modification.&quot; Cache metadata is persisted alongside the index and restored on server restart, and Clang&#39;s own PCM validation remains as the final backstop.</p><h3 id="integration-with-the-compilation-pipeline" tabindex="-1">Integration with the Compilation Pipeline <a class="header-anchor" href="#integration-with-the-compilation-pipeline" aria-label="Permalink to &quot;Integration with the Compilation Pipeline&quot;">​</a></h3><p>Before a document AST or interactive build is dispatched, its dependency preparation acquires the needed PCM nodes — this is the first step of compilation preparation, executed before PCH construction. The import scan runs on the request&#39;s actual buffer text (including any synthesized suffix for header contexts), so an <code>import m;</code> the user has typed but not yet saved still gets its PCM built before the parse needs it.</p><h2 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h2><ul><li><p><strong>Why interest counting instead of a task queue?</strong> A task queue cannot express &quot;no one needs this compilation anymore.&quot; When the user closes the file that triggered a compilation, continuing wastes resources. Interest counting precisely tracks demand, making cancellation decisions grounded — not based on timeouts or heuristics, but on whether any request is still waiting for the result.</p></li><li><p><strong>Why defer zero-interest cancellation instead of cancelling immediately?</strong> In an event loop model, multiple steps of an operation complete within the same tick. When a compilation request is superseded, the old interest is released and the new one established shortly after, with a momentary zero in between. Immediate cancellation would unnecessarily wind down shared dependencies — deferring the check ensures interest handoffs don&#39;t trigger cancellation.</p></li><li><p><strong>Why cooperative cancellation instead of destroying the build task?</strong> Destroying a coroutine frame mid-build makes every await point a potential exit, and the commit sequence at the end of a build (write artifact, register metadata) must never be split in half. Advisory stop flags let the build exit at well-defined checkpoints and always publish a real outcome, at the cost of slightly delayed cancellation.</p></li><li><p><strong>Why a generation counter instead of locks?</strong> The master process is a single-threaded event loop with no data races. The &quot;races&quot; to detect come from asynchronous timing — &quot;was the file updated during compilation?&quot; The generation counter answers this with minimal overhead, without introducing locks.</p></li><li><p><strong>Why lazy dependency resolution?</strong> Dependency resolution requires running the Clang preprocessor (precise scanning) on each module file, which is not cheap. If all module dependencies were resolved at startup, it would add to startup time. Lazy resolution ensures only modules actually needed for compilation are scanned — opening a file doesn&#39;t trigger scanning the entire module graph.</p></li><li><p><strong>Why are failures not sticky?</strong> Users are actively editing code — syntax errors are the norm. If failures were marked as persistent, users couldn&#39;t get correct results after fixing errors without restarting the server. Retaining the dirty flag lets the next request naturally trigger a retry.</p></li><li><p><strong>Why store PCMs in a separate cache directory?</strong> clangd shares PCM files with the build system, which causes file-locking conflicts — the language server holds the PCM open, preventing the build system from overwriting it (see <a href="https://github.com/clangd/clangd/issues/2292" target="_blank" rel="noreferrer">clangd/clangd#2292</a>). clice keeps its PCMs in its own cache directory, avoiding this problem. The trade-off is additional disk space usage and extra time for first-time compilation.</p></li></ul><h2 id="known-limitations" tabindex="-1">Known Limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known Limitations&quot;">​</a></h2><ul><li><p><strong>Dependency resolution determinism.</strong> A time window exists between resolving dependencies and the actual compilation. If a file is modified during this window, the resolved dependencies may not match the actual dependencies at compilation time. The generation counter detects this and triggers retries, but at the cost of extra compilation overhead.</p></li><li><p><strong>Brand-new module providers.</strong> An <code>import</code> whose provider module has never been saved to disk cannot be built — there is no file to compile. Once the provider is saved it is discovered through the placeholder-node mechanism; an import chain that was previously unresolvable heals when its dependents are next edited or reopened, not spontaneously.</p></li><li><p><strong>Graph state is in-memory.</strong> Node and edge state does not survive a server restart; the graph is rebuilt lazily from the persisted caches and the dependency registry on the next run.</p></li></ul>`,63)])])}const m=t(s,[["render",o]]);export{u as __pageData,m as default};
